package com.razvanprajanu.seniorprep

import com.facebook.react.BaseReactPackage
import com.facebook.react.bridge.NativeModule
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.module.model.ReactModuleInfo
import com.facebook.react.module.model.ReactModuleInfoProvider
import com.razvanprajanu.seniorprep.files.DataFilesModule
import com.razvanprajanu.seniorprep.reminder.DailyReminderModule

/** The app's own TurboModules (specs in src/native/specs, generated by codegen). */
class SeniorPrepPackage : BaseReactPackage() {
  override fun getModule(name: String, reactContext: ReactApplicationContext): NativeModule? =
    when (name) {
      DataFilesModule.NAME -> DataFilesModule(reactContext)
      DailyReminderModule.NAME -> DailyReminderModule(reactContext)
      else -> null
    }

  override fun getReactModuleInfoProvider(): ReactModuleInfoProvider = ReactModuleInfoProvider {
    mapOf(
      DataFilesModule.NAME to turboModule(DataFilesModule.NAME, DataFilesModule::class.java),
      DailyReminderModule.NAME to
        turboModule(DailyReminderModule.NAME, DailyReminderModule::class.java),
    )
  }

  private fun turboModule(name: String, type: Class<*>) =
    ReactModuleInfo(
      name = name,
      className = type.name,
      canOverrideExistingModule = false,
      needsEagerInit = false,
      isCxxModule = false,
      isTurboModule = true,
    )
}
